#!/system/bin/sh
# Kernel Driver Loader — Zero-Footprint RT Driver
# Target: Xiaomi Mi A2 Lite (daisy) — DaisyForGaming 4.9.337
# Vermagic: 4.9.337-DaisyForGaming SMP preempt mod_unload modversions aarch64

if [ "$(id -u)" != "0" ]; then
  echo "[-] Error: Root permission required." >&2
  exit 1
fi

MODULE_BASE64=""

TEMP_KO="/data/local/tmp/rt_daisy.ko"
echo "$MODULE_BASE64" | base64 -d > "$TEMP_KO"

if [ ! -s "$TEMP_KO" ]; then
  echo "[-] Error: Failed to extract driver module." >&2
  rm -f "$TEMP_KO"
  exit 1
fi

echo "[*] Inserting kernel module..."
ERR=$(insmod "$TEMP_KO" 2>&1)
RET=$?

# Immediate zero-footprint clean exit: delete on-disk file
rm -f "$TEMP_KO"

if [ $RET -eq 0 ]; then
  echo "[+] Driver loaded successfully!"
  echo "[+] In-kernel stealth unlinking active (hidden from /proc/modules)."
  echo "[+] Device nodes active with 0666 permissions."
  echo "[+] On-disk staging file wiped."
  exit 0
else
  echo "[-] insmod failed: $ERR" >&2
  exit 1
fi
